package com.networkmonitorpro.service; import android.app.*; import android.content.*; import android.os.*; import com.networkmonitorpro.network.*; public class DownloadService extends Service{ public static final String ACTION_ADD="add", EXTRA_URL="url", EXTRA_OVERRIDE="override"; NetworkDetector detector; boolean fiveG=true; public void onCreate(){super.onCreate(); startForeground(202,NotificationHelper.download(this,"Download manager",0)); detector=new NetworkDetector(this); detector.snapshots.observeForever(s->{fiveG=s.is5g();}); detector.start();} public int onStartCommand(Intent i,int f,int id){ if(i!=null&&ACTION_ADD.equals(i.getAction())){String u=i.getStringExtra(EXTRA_URL); boolean over=i.getBooleanExtra(EXTRA_OVERRIDE,false); if(fiveG||over){ String name=u==null?"download.bin":android.net.Uri.parse(u).getLastPathSegment(); if(name==null||name.isEmpty())name="download.bin"; FetchDownloadController.get(this).enqueue(u, new java.io.File(getExternalFilesDir(null), name).getAbsolutePath()); startForeground(202,NotificationHelper.download(this,u==null?"Download":u,1)); } else NotificationHelper.alert(this,"Download paused","Waiting for 5G to resume queued downloads");} return START_STICKY;} public IBinder onBind(Intent i){return null;} public void onDestroy(){if(detector!=null)detector.stop();super.onDestroy();} }
